using System.Text.Json;
using BotTraversal.Core;
using P=BotTraversal.Core.FollowerCapabilityPreparationPolicy;
var cases=new List<string>();void Check(bool ok,string label){if(!ok)throw new Exception("FAIL "+label);cases.Add(label);}
Check(P.CanMaterialize(34,false,1215,1209),"deferred first DropDown remains eligible after active Climb blocks append");
Check(P.CanMaterialize(34,false,1215,1209),"reading later episode35 cannot retire unmaterialized episode34");
Check(!P.CanMaterialize(34,true,1215,1209),"materialized episode cannot be duplicated");
Check(!P.CanMaterialize(0,false,1215,1209),"missing episode cannot acquire route identity");
Check(!P.CanMaterialize(34,false,1209,1209),"consumed execution floor remains authoritative");
Check(!P.CanMaterialize(34,false,1208,1209),"earlier consumed episode cannot return");
float deadline=P.FreshDeadline(313.2446f,310.351135f,45,true,310.306274f,277.4644f);
Check(deadline>355.35f&&deadline<355.36f,"independent fresh Climb receives existing full mission lifetime");
Check(313.705627f<deadline,"recorded Climb completion cannot inherit old Jump expiry");
Check(319.935944f<deadline,"recorded same-chain second DropDown retains fresh mission epoch");
Check(P.FreshDeadline(313,310,45,false,310,277)==313,"same execution debt cannot refresh TTL");
Check(P.FreshDeadline(313,310,45,true,269,277)==313,"old demonstration cannot renew recovery epoch");
Check(P.FreshDeadline(313,310,45,true,277,277)==313,"equal terminal timestamp cannot count as fresh");
Check(P.FreshDeadline(500,310,45,true,310,277)==500,"fresh epoch never shortens existing deadline");
Check(P.FreshDeadline(313,310,0,true,310,277)==313,"invalid lifetime cannot extend route");
Check(P.FreshDeadline(313,float.NaN,45,true,310,277)==313,"invalid clock cannot manufacture lease");
Check(P.LandingHold(true,true,true,true,.462628841f,.187701061f,.209182471f,.093f,.42f),"recorded first contact is protected by one native motion forecast");
Check(!P.LandingHold(true,true,true,true,.462628841f,.187701061f,.209182471f,.02f,.42f),"distant candidate outside native one-motion horizon remains untouched");
Check(P.LandingHold(true,true,true,true,.321395159f,.10623613f,.190f,.08f,.42f),"recorded near-entry pending proof stops advance at current supported sample");
Check(!P.LandingHold(false,true,true,true,.1f,.1f,.1f,.08f,.42f),"no landing candidate cannot create landing hold");
Check(!P.LandingHold(true,false,true,true,.1f,.1f,.1f,.08f,.42f),"missing airborne evidence cannot borrow predecessor hold");
Check(!P.LandingHold(true,true,false,true,.1f,.1f,.1f,.08f,.42f),"missing descent cannot borrow predecessor hold");
Check(!P.LandingHold(true,true,true,false,.1f,.1f,.1f,.08f,.42f),"near-side body cannot be held as completed far-side approach");
Check(!P.LandingHold(true,true,true,true,.1f,.201f,.1f,.08f,.42f),"adjacent corridor is not widened");
Check(!P.LandingHold(true,true,true,true,.1f,.1f,.301f,.08f,.42f),"lower landing cannot masquerade as upper frontier");
Check(!P.LandingHold(true,true,true,true,-.03181931f,.066f,.15f,.08f,.42f),"recorded already-passed entry is never rewound");
Check(!P.LandingHold(true,true,true,true,float.NaN,.1f,.1f,.08f,.42f),"invalid geometry cannot constrain body");
Check(P.CanPrepare(true,true,true,true,false),"aligned live grounded preparation may issue actual run-up input");
Check(!P.CanPrepare(false,true,true,true,false),"airborne preparation cannot acquire ground input");
Check(!P.CanPrepare(true,false,true,true,false),"remote route target cannot acquire preparation consumer");
Check(!P.CanPrepare(true,true,false,true,false),"uncentered preparation retains original alignment producer");
Check(!P.CanPrepare(true,true,true,false,false),"misfacing preparation retains original steering");
Check(!P.CanPrepare(true,true,true,true,true),"terminal recovery must own locomotion without preparation reacquisition");
File.WriteAllText(args[0],JsonSerializer.Serialize(new{passed=true,checks=cases.Count,cases,physicsSimulated=false},new JsonSerializerOptions{WriteIndented=true}));
Console.WriteLine($"PASS {cases.Count} compiled preparation and epoch-continuity checks");
